import json,hashlib,os
def sf(p):
    h=hashlib.sha256()
    with open(p,'rb') as f:
        for b in iter(lambda:f.read(1<<20),b''): h.update(b)
    return h.hexdigest()
out={}
for pf in ['docs/coop/design-corrections/native/source-pins.v2.json',
           'docs/coop/design-corrections/foundation/source-pins.v1.json',
           'docs/coop/design-corrections/security/source-pins.v1.json',
           'docs/coop/design-corrections/workflows/source-pins.v1.json']:
    d=json.load(open(pf))
    pins=d['pins'] if isinstance(d,dict) and 'pins' in d else None
    if pins is None:
        print(pf,'NO pins key; keys=',list(d.keys())); continue
    bad=[];miss=[]
    for e in pins:
