    print(pf,'entries=',len(pins),'mismatch=',len(bad),'missing=',len(miss))
    for x in bad[:10]: print('   MISMATCH',x)
    for x in miss[:10]: print('   MISSING',x)
    out[pf]={'entries':len(pins),'mismatch':bad,'missing':miss}
